import {
  createContext,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

import {
  focusElement,
  getFocusableElements,
  isTopDialog,
  registerDialogLayer,
} from './dialog-layer'

export type DialogOpenChangeReason = 'close' | 'escape' | 'outside-pointer' | 'trigger'

export type DialogOpenChangeDetails = {
  reason: DialogOpenChangeReason
}

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
  open?: boolean
}

type DialogContextValue = {
  contentId: string
  descriptionId: string
  open: boolean
  setOpen: (open: boolean, reason: DialogOpenChangeReason) => void
  titleId: string
}

const DialogContext = createContext<DialogContextValue | null>(null)
const useBrowserLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect

function useDialogContext(componentName: string) {
  const context = useContext(DialogContext)
  if (!context) throw new Error(`${componentName} must be rendered inside Dialog.Root`)
  return context
}

export function DialogRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open: controlledOpen,
}: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const open = controlledOpen ?? uncontrolledOpen
  const contentId = useId()
  const titleId = useId()
  const descriptionId = useId()

  const setOpen = useCallback(
    (nextOpen: boolean, reason: DialogOpenChangeReason) => {
      if (nextOpen === open) return
      if (controlledOpen === undefined) setUncontrolledOpen(nextOpen)
      onOpenChange?.(nextOpen, { reason })
    },
    [controlledOpen, onOpenChange, open],
  )

  const value = useMemo(
    () => ({ contentId, descriptionId, open, setOpen, titleId }),
    [contentId, descriptionId, open, setOpen, titleId],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

export type DialogTriggerProps = React.ButtonHTMLAttributes<HTMLButtonElement>

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(function DialogTrigger(
  { onClick, type = 'button', ...props },
  forwardedRef,
) {
  const { contentId, open, setOpen } = useDialogContext('Dialog.Trigger')
  return (
    <button
      {...props}
      aria-controls={open ? contentId : undefined}
      aria-expanded={open}
      aria-haspopup="dialog"
      data-state={open ? 'open' : 'closed'}
      onClick={(event) => {
        onClick?.(event)
        if (!event.defaultPrevented) setOpen(true, 'trigger')
      }}
      ref={forwardedRef}
      type={type}
    />
  )
})

export type DialogPortalProps = {
  children: ReactNode
  container?: Element | DocumentFragment | null
}

export function DialogPortal({ children, container }: DialogPortalProps) {
  const { open } = useDialogContext('Dialog.Portal')
  const [portalNode, setPortalNode] = useState<HTMLDivElement | null>(null)

  useBrowserLayoutEffect(() => {
    if (!open) return

    const target = container ?? document.body
    const node = document.createElement('div')
    node.dataset.dialogPortal = ''
    target.appendChild(node)
    setPortalNode(node)

    return () => {
      node.remove()
      setPortalNode(null)
    }
  }, [container, open])

  if (!open || !portalNode) return null
  return createPortal(children, portalNode)
}

export type DialogOverlayProps = HTMLAttributes<HTMLDivElement>

export const DialogOverlay = forwardRef<HTMLDivElement, DialogOverlayProps>(function DialogOverlay(
  { onPointerDown, ...props },
  forwardedRef,
) {
  const { open, setOpen } = useDialogContext('Dialog.Overlay')
  if (!open) return null

  return (
    <div
      {...props}
      data-state="open"
      onPointerDown={(event) => {
        onPointerDown?.(event)
        if (event.defaultPrevented || event.target !== event.currentTarget) return

        event.preventDefault()
        setOpen(false, 'outside-pointer')
      }}
      ref={forwardedRef}
    />
  )
})

export type DialogAutoFocusEvent = {
  readonly defaultPrevented: boolean
  preventDefault: () => void
}

function createAutoFocusEvent(): DialogAutoFocusEvent {
  let defaultPrevented = false
  return {
    get defaultPrevented() {
      return defaultPrevented
    },
    preventDefault() {
      defaultPrevented = true
    },
  }
}

export type DialogContentProps = HTMLAttributes<HTMLDivElement> & {
  finalFocusRef?: RefObject<HTMLElement | null>
  initialFocusRef?: RefObject<HTMLElement | null>
  onCloseAutoFocus?: (event: DialogAutoFocusEvent) => void
  onOpenAutoFocus?: (event: DialogAutoFocusEvent) => void
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') ref(value)
  else if (ref) ref.current = value
}

export const DialogContent = forwardRef<HTMLDivElement, DialogContentProps>(function DialogContent(
  {
    'aria-describedby': ariaDescribedBy,
    'aria-labelledby': ariaLabelledBy,
    finalFocusRef,
    initialFocusRef,
    onCloseAutoFocus,
    onKeyDown,
    onOpenAutoFocus,
    tabIndex = -1,
    ...props
  },
  forwardedRef,
) {
  const { contentId, descriptionId, open, setOpen, titleId } = useDialogContext('Dialog.Content')
  const contentRef = useRef<HTMLDivElement | null>(null)
  const effectVersion = useRef(0)

  useBrowserLayoutEffect(() => {
    const content = contentRef.current
    if (!open || !content) return

    const version = ++effectVersion.current
    const previouslyFocused = document.activeElement instanceof HTMLElement ? document.activeElement : null
    const portalRoot = content.closest<HTMLElement>('[data-dialog-portal]') ?? content
    const layer = { content, lastFocusedInside: null as HTMLElement | null, portalRoot }
    const unregister = registerDialogLayer(layer)

    const handleFocusIn = (event: FocusEvent) => {
      if (!isTopDialog(content)) return
      const target = event.target
      if (target instanceof HTMLElement && content.contains(target)) {
        layer.lastFocusedInside = target
        return
      }

      const fallback =
        (layer.lastFocusedInside?.isConnected ? layer.lastFocusedInside : null) ??
        getFocusableElements(content)[0] ??
        content
      focusElement(fallback)
    }

    document.addEventListener('focusin', handleFocusIn)

    const openEvent = createAutoFocusEvent()
    onOpenAutoFocus?.(openEvent)
    if (!openEvent.defaultPrevented) {
      const requestedInitialFocus = initialFocusRef?.current
      const initialFocus =
        (requestedInitialFocus && content.contains(requestedInitialFocus)
          ? requestedInitialFocus
          : null) ??
        content.querySelector<HTMLElement>('[autofocus]') ??
        getFocusableElements(content)[0] ??
        content
      focusElement(initialFocus)
      layer.lastFocusedInside = initialFocus
    }

    return () => {
      document.removeEventListener('focusin', handleFocusIn)
      unregister()

      queueMicrotask(() => {
        // React Strict Mode immediately mounts the effect again in development.
        if (effectVersion.current !== version) return
        const closeEvent = createAutoFocusEvent()
        onCloseAutoFocus?.(closeEvent)
        if (!closeEvent.defaultPrevented) {
          focusElement(finalFocusRef?.current ?? previouslyFocused)
        }
      })
    }
  }, [finalFocusRef, initialFocusRef, onCloseAutoFocus, onOpenAutoFocus, open])

  if (!open) return null

  return (
    <div
      {...props}
      aria-describedby={ariaDescribedBy ?? descriptionId}
      aria-labelledby={ariaLabelledBy ?? titleId}
      aria-modal="true"
      data-state="open"
      id={contentId}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (event.defaultPrevented || !isTopDialog(contentRef.current)) return

        if (event.key === 'Escape') {
          event.preventDefault()
          event.stopPropagation()
          setOpen(false, 'escape')
          return
        }

        if (event.key !== 'Tab' || !contentRef.current) return
        const focusable = getFocusableElements(contentRef.current)
        if (focusable.length === 0) {
          event.preventDefault()
          focusElement(contentRef.current)
          return
        }

        const first = focusable[0]
        const last = focusable.at(-1)!
        const active = document.activeElement
        if (event.shiftKey && (active === first || !contentRef.current.contains(active))) {
          event.preventDefault()
          focusElement(last)
        } else if (!event.shiftKey && (active === last || !contentRef.current.contains(active))) {
          event.preventDefault()
          focusElement(first)
        }
      }}
      ref={(node) => {
        contentRef.current = node
        assignRef(forwardedRef, node)
      }}
      role="dialog"
      tabIndex={tabIndex}
    />
  )
})

export type DialogTitleProps = Omit<React.HTMLAttributes<HTMLHeadingElement>, 'id'>

export const DialogTitle = forwardRef<HTMLHeadingElement, DialogTitleProps>(function DialogTitle(
  props,
  forwardedRef,
) {
  const { titleId } = useDialogContext('Dialog.Title')
  return <h2 {...props} id={titleId} ref={forwardedRef} />
})

export type DialogDescriptionProps = Omit<React.HTMLAttributes<HTMLParagraphElement>, 'id'>

export const DialogDescription = forwardRef<HTMLParagraphElement, DialogDescriptionProps>(
  function DialogDescription(props, forwardedRef) {
    const { descriptionId } = useDialogContext('Dialog.Description')
    return <p {...props} id={descriptionId} ref={forwardedRef} />
  },
)

export type DialogCloseProps = React.ButtonHTMLAttributes<HTMLButtonElement>

export const DialogClose = forwardRef<HTMLButtonElement, DialogCloseProps>(function DialogClose(
  { onClick, type = 'button', ...props },
  forwardedRef,
) {
  const { setOpen } = useDialogContext('Dialog.Close')
  return (
    <button
      {...props}
      onClick={(event) => {
        onClick?.(event)
        if (!event.defaultPrevented) setOpen(false, 'close')
      }}
      ref={forwardedRef}
      type={type}
    />
  )
})

export const Dialog = {
  Close: DialogClose,
  Content: DialogContent,
  Description: DialogDescription,
  Overlay: DialogOverlay,
  Portal: DialogPortal,
  Root: DialogRoot,
  Title: DialogTitle,
  Trigger: DialogTrigger,
}

